{"id":"f208e978-ad65-4e8d-b7e6-2c2cf1f1da62","recipe_group_id":"5ac97df2-0a4e-4f3b-8bf3-ef91206b074d","language":"es","slug":"tarta-de-manzana-clasica","public_path":"/tarta-de-manzana-clasica","source_url":null,"title":"Tarta de manzana clásica","excerpt":"Tarta de manzana clásica con masa quebrada casera y manzanas en láminas finas con canela. Se hornea en un molde de 24 cm y rinde 8 porciones.","summary":"Esta tarta de manzana lleva una masa quebrada de harina, mantequilla fría y huevo, y un relleno de manzanas en láminas finas con limón, azúcar y canela. Se coloca en círculos concéntricos y se hornea hasta que los bordes quedan dorados y crujientes.\n\nLleva 60 minutos de preparación, 30 de ellos de reposo de la masa, y 45 de horno. Rinde 8 porciones en un molde de 24 cm.","category":"Postres","difficulty":"Media","course":"Postre","cuisine":"Internacional","prep_time_minutes":60,"cook_time_minutes":45,"total_time_minutes":105,"servings":8,"keywords":["tarta de manzana","receta de tarta de manzana","tarta de manzana clásica","cómo hacer tarta de manzana","tarta de manzana con masa quebrada","tarta de manzana casera","tarta de manzana con canela"],"ingredients":[{"name":"harina de trigo","amount":"250","unit":"g","group":"Para la masa"},{"name":"mantequilla sin sal fría","amount":"125","unit":"g","group":"Para la masa"},{"name":"azúcar","amount":"50","unit":"g","group":"Para la masa"},{"name":"huevo","amount":"1","unit":"","group":"Para la masa"},{"name":"sal","amount":"1/4","unit":"cucharadita","group":"Para la masa"},{"name":"manzanas","amount":"5","unit":"","group":"Para el relleno"},{"name":"limón","amount":"1/2","unit":"","group":"Para el relleno"},{"name":"azúcar","amount":"40","unit":"g","group":"Para el relleno"},{"name":"canela en polvo","amount":"1","unit":"cucharadita","group":"Para el relleno"},{"name":"mantequilla sin sal","amount":"30","unit":"g","group":"Para el relleno"}],"steps":[{"title":"Prepara los ingredientes","content":"Ten a mano 250 g de harina, 125 g de mantequilla sin sal bien fría, 50 g de azúcar, 1 huevo, sal, 5 manzanas, 1 limón y canela. Para el relleno necesitas además 40 g de azúcar y 30 g de mantequilla. Cuanto más fría esté la mantequilla, más crujiente quedará la masa.","image_url":"/recetas/tarta-de-manzana-clasica/paso-01.webp","image_alt":"Tarta de manzana clásica: Prepara los ingredientes"},{"title":"Haz la masa","content":"En un bol grande mezcla 250 g de harina, 50 g de azúcar y ¼ de cucharadita de sal. Añade 125 g de mantequilla fría en cubos y desmenúzala con las yemas de los dedos hasta que parezca arena gruesa. Agrega el huevo y une la masa sin amasar de más; si queda seca, añade unas gotas de agua fría.","image_url":"/recetas/tarta-de-manzana-clasica/paso-02.webp","image_alt":"Tarta de manzana clásica: Haz la masa"},{"title":"Reposa la masa","content":"Forma un disco plano, envuélvelo en film transparente y déjalo reposar 30 minutos en la nevera. Mientras tanto, precalienta el horno a 190 °C.","image_url":"/recetas/tarta-de-manzana-clasica/paso-03.webp","image_alt":"Tarta de manzana clásica: Reposa la masa"},{"title":"Corta las manzanas","content":"Pela las manzanas, quítales el corazón y córtalas en láminas de 3 mm. Mezcla las láminas con el jugo de ½ limón para que no se oscurezcan.","image_url":"/recetas/tarta-de-manzana-clasica/paso-04.webp","image_alt":"Tarta de manzana clásica: Corta las manzanas"},{"title":"Forra el molde","content":"Extiende la masa con un rodillo hasta unos 3 mm de grosor y forra un molde de 24 cm. Presiónala contra las paredes, recorta el exceso del borde y pincha la base con un tenedor.","image_url":"/recetas/tarta-de-manzana-clasica/paso-05.webp","image_alt":"Tarta de manzana clásica: Forra el molde"},{"title":"Monta la tarta","content":"Coloca las láminas de manzana ligeramente solapadas, en círculos concéntricos. Mezcla 40 g de azúcar con 1 cucharadita de canela, espolvorea por encima y reparte 30 g de mantequilla en trocitos.","image_url":"/recetas/tarta-de-manzana-clasica/paso-06.webp","image_alt":"Tarta de manzana clásica: Monta la tarta"},{"title":"Hornea","content":"Hornea en la rejilla del medio durante 45 minutos, hasta que los bordes estén dorados y las manzanas tiernas al pincharlas. Si la superficie se dora demasiado pronto, cúbrela con papel de aluminio. Sácala y déjala sobre una rejilla.","image_url":"/recetas/tarta-de-manzana-clasica/paso-07.webp","image_alt":"Tarta de manzana clásica: Hornea"},{"title":"Enfría y sirve","content":"Deja enfriar 20 minutos antes de desmoldar. Corta 8 porciones y sirve la tarta tibia o a temperatura ambiente.","image_url":"/recetas/tarta-de-manzana-clasica/paso-08.webp","image_alt":"Tarta de manzana clásica: Enfría y sirve"}],"image_url":"/recetas/tarta-de-manzana-clasica/portada.webp","gallery":[{"url":"/recetas/tarta-de-manzana-clasica/portada.webp","alt":"Tarta de manzana clásica"}],"notes":"Usa manzanas firmes y ligeramente ácidas, como Granny Smith, Golden o Reineta, que no se deshacen al hornear. Lamina con un cuchillo bien afilado para que todas las láminas tengan el mismo grosor. La masa se puede preparar el día anterior y guardar en la nevera. La tarta se conserva 2 días a temperatura ambiente o 4 días en la nevera, tapada; para recuperar el crujiente, caliéntala 10 minutos a 160 °C.","nutrition":{"calories":346,"protein_g":4.4,"carbs_g":46,"fat_g":16.7,"sodium_mg":84,"serving_size":"1 porción (1/8 de tarta, unos 140 g)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Suma de nutrientes por 100 g multiplicados por los pesos de los ingredientes y divididos entre 8 porciones: 250 g de harina, 125 g de mantequilla sin sal y 50 g de azúcar de la masa, 50 g de huevo, 1,5 g de sal, 650 g de manzana pelada y sin corazón, 25 g de jugo de limón, 40 g de azúcar, 2,6 g de canela y 30 g de mantequilla sin sal del relleno, todo contado.","note":"Estimación por porción. Los valores cambian según el tamaño de las manzanas y el grosor de la masa.","inputs":[{"fdc_id":"169761","description":"Wheat flour, white, all-purpose, enriched (250 g)","grams":250,"per100":{"calories":364,"protein_g":10.33,"carbs_g":76.31,"fat_g":0.98,"saturated_fat_g":0.155,"fiber_g":2.7,"sodium_mg":2}},{"fdc_id":"173430","description":"Butter, without salt (125 g, masa)","grams":125,"per100":{"calories":717,"protein_g":0.85,"carbs_g":0.06,"fat_g":81.11,"saturated_fat_g":51.368,"fiber_g":0,"sodium_mg":11}},{"fdc_id":"169655","description":"Sugars, granulated (50 g, masa)","grams":50,"per100":{"calories":387,"protein_g":0,"carbs_g":99.98,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sodium_mg":1}},{"fdc_id":"171287","description":"Egg, whole, raw, fresh (1 huevo grande ≈ 50 g)","grams":50,"per100":{"calories":143,"protein_g":12.56,"carbs_g":0.72,"fat_g":9.51,"saturated_fat_g":3.126,"fiber_g":0,"sodium_mg":142}},{"fdc_id":"173468","description":"Salt, table (¼ cucharadita ≈ 1,5 g)","grams":1.5,"per100":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sodium_mg":38758}},{"fdc_id":"168203","description":"Apples, raw, without skin (5 manzanas ≈ 800 g enteras; ≈ 650 g peladas y sin corazón)","grams":650,"per100":{"calories":48,"protein_g":0.27,"carbs_g":12.76,"fat_g":0.13,"saturated_fat_g":0.022,"fiber_g":2.1,"sodium_mg":0}},{"fdc_id":"167747","description":"Lemon juice, raw (½ limón ≈ 25 g de jugo)","grams":25,"per100":{"calories":22,"protein_g":0.35,"carbs_g":6.9,"fat_g":0.24,"saturated_fat_g":0.039,"fiber_g":0.3,"sodium_mg":1}},{"fdc_id":"169655","description":"Sugars, granulated (40 g, relleno)","grams":40,"per100":{"calories":387,"protein_g":0,"carbs_g":99.98,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sodium_mg":1}},{"fdc_id":"171320","description":"Spices, cinnamon, ground (1 cucharadita ≈ 2,6 g)","grams":2.6,"per100":{"calories":247,"protein_g":3.99,"carbs_g":80.59,"fat_g":1.24,"saturated_fat_g":0.345,"fiber_g":53.1,"sodium_mg":10}},{"fdc_id":"173430","description":"Butter, without salt (30 g, relleno)","grams":30,"per100":{"calories":717,"protein_g":0.85,"carbs_g":0.06,"fat_g":81.11,"saturated_fat_g":51.368,"fiber_g":0,"sodium_mg":11}}]},"seo":{"title":"Tarta de manzana clásica con masa quebrada casera | Manual de Cocina","description":"Tarta de manzana clásica con masa quebrada casera y manzanas en láminas finas con canela. Molde de 24 cm, 8 porciones. Paso a paso con fotos.","image_variants":["/recetas/tarta-de-manzana-clasica/portada-1x1.webp","/recetas/tarta-de-manzana-clasica/portada-4x3.webp","/recetas/tarta-de-manzana-clasica/portada-16x9.webp"],"faq":[{"q":"¿Qué manzanas son mejores para una tarta de manzana?","a":"Las firmes y ligeramente ácidas, como Granny Smith, Golden o Reineta, porque mantienen la forma al hornearse y equilibran el dulzor."},{"q":"¿Por qué hay que enfriar la masa antes de extenderla?","a":"Reposar 30 minutos en la nevera enfría la mantequilla y relaja la masa. Así se extiende mejor, no encoge al hornearse y queda crujiente."},{"q":"¿Cuánto dura la tarta de manzana?","a":"Hasta 2 días a temperatura ambiente y 4 días en la nevera, tapada. Para recuperar el crujiente, caliéntala 10 minutos a 160 °C."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"e20041f9-30ce-5324-84c0-11fa1fb0f3d4","recipe_group_id":"5ac97df2-0a4e-4f3b-8bf3-ef91206b074d","language":"de","slug":"klassische-apfeltarte","public_path":"/de/klassische-apfeltarte","source_url":null,"title":"Klassische Apfeltarte mit Mürbeteig","excerpt":"Klassische Apfeltarte mit selbstgemachtem Mürbeteig und dünn geschnittenen Äpfeln mit Zimt. Gebacken in einer 24-cm-Form, 8 Stücke.","summary":"Diese Apfeltarte besteht aus einem Mürbeteig aus Mehl, kalter Butter und Ei und einem Belag aus dünn geschnittenen Äpfeln mit Zitrone, Zucker und Zimt. Die Apfelscheiben werden in konzentrischen Kreisen gelegt, und die Tarte backt, bis der Rand goldbraun und knusprig ist.\n\nSie braucht 60 Minuten Vorbereitung, davon 30 Minuten Ruhezeit für den Teig, und 45 Minuten im Ofen. Ergibt 8 Stücke in einer 24-cm-Form.","category":"Desserts","difficulty":"Mittel","course":"Dessert","cuisine":"International","prep_time_minutes":60,"cook_time_minutes":45,"total_time_minutes":105,"servings":8,"keywords":["Apfeltarte","Apfeltarte Rezept","klassische Apfeltarte","Apfeltarte selber machen","Apfeltarte mit Mürbeteig","Apfeltarte einfach","Apfeltarte mit Zimt"],"ingredients":[{"name":"Weizenmehl","amount":"250","unit":"g","group":"Für den Teig"},{"name":"kalte ungesalzene Butter","amount":"125","unit":"g","group":"Für den Teig"},{"name":"Zucker","amount":"50","unit":"g","group":"Für den Teig"},{"name":"Ei","amount":"1","unit":"","group":"Für den Teig"},{"name":"Salz","amount":"1/4","unit":"Teelöffel","group":"Für den Teig"},{"name":"Äpfel","amount":"5","unit":"","group":"Für den Belag"},{"name":"Zitrone","amount":"1/2","unit":"","group":"Für den Belag"},{"name":"Zucker","amount":"40","unit":"g","group":"Für den Belag"},{"name":"gemahlener Zimt","amount":"1","unit":"Teelöffel","group":"Für den Belag"},{"name":"ungesalzene Butter","amount":"30","unit":"g","group":"Für den Belag"}],"steps":[{"title":"Zutaten vorbereiten","content":"Bereiten Sie 250 g Mehl, 125 g sehr kalte ungesalzene Butter, 50 g Zucker, 1 Ei, Salz, 5 Äpfel, 1 Zitrone und Zimt bereit. Für den Belag brauchen Sie außerdem 40 g Zucker und 30 g Butter. Je kälter die Butter, desto knuspriger wird der Teig.","image_url":"/recetas/tarta-de-manzana-clasica/paso-01.webp","image_alt":"Klassische Apfeltarte mit Mürbeteig: Zutaten vorbereiten"},{"title":"Teig zubereiten","content":"In einer großen Schüssel 250 g Mehl, 50 g Zucker und ¼ Teelöffel Salz mischen. 125 g kalte Butter in Würfeln dazugeben und mit den Fingerspitzen zerbröseln, bis die Masse grobem Sand ähnelt. Das Ei zugeben und den Teig rasch zusammenfügen, ohne ihn zu lange zu kneten; ist er zu trocken, einige Tropfen kaltes Wasser zugeben.","image_url":"/recetas/tarta-de-manzana-clasica/paso-02.webp","image_alt":"Klassische Apfeltarte mit Mürbeteig: Teig zubereiten"},{"title":"Teig ruhen lassen","content":"Den Teig zu einer flachen Scheibe formen, in Frischhaltefolie wickeln und 30 Minuten im Kühlschrank ruhen lassen. In der Zwischenzeit den Ofen auf 190 °C vorheizen.","image_url":"/recetas/tarta-de-manzana-clasica/paso-03.webp","image_alt":"Klassische Apfeltarte mit Mürbeteig: Teig ruhen lassen"},{"title":"Äpfel schneiden","content":"Die Äpfel schälen, entkernen und in 3 mm dünne Scheiben schneiden. Die Scheiben mit dem Saft einer halben Zitrone mischen, damit sie nicht braun werden.","image_url":"/recetas/tarta-de-manzana-clasica/paso-04.webp","image_alt":"Klassische Apfeltarte mit Mürbeteig: Äpfel schneiden"},{"title":"Form auslegen","content":"Den Teig mit einem Nudelholz auf etwa 3 mm Dicke ausrollen und eine 24-cm-Form damit auslegen. Den Teig an die Wand drücken, überstehenden Rand abschneiden und den Boden mit einer Gabel einstechen.","image_url":"/recetas/tarta-de-manzana-clasica/paso-05.webp","image_alt":"Klassische Apfeltarte mit Mürbeteig: Form auslegen"},{"title":"Tarte belegen","content":"Die Apfelscheiben leicht überlappend in konzentrischen Kreisen auflegen. 40 g Zucker mit 1 Teelöffel Zimt mischen, darüberstreuen und 30 g Butter in kleinen Stücken verteilen.","image_url":"/recetas/tarta-de-manzana-clasica/paso-06.webp","image_alt":"Klassische Apfeltarte mit Mürbeteig: Tarte belegen"},{"title":"Backen","content":"Auf der mittleren Schiene 45 Minuten backen, bis der Rand goldbraun ist und die Äpfel beim Einstechen weich sind. Wird die Oberfläche zu früh dunkel, mit Alufolie abdecken. Herausnehmen und auf einem Gitter abstellen.","image_url":"/recetas/tarta-de-manzana-clasica/paso-07.webp","image_alt":"Klassische Apfeltarte mit Mürbeteig: Backen"},{"title":"Abkühlen und servieren","content":"Vor dem Herauslösen 20 Minuten abkühlen lassen. In 8 Stücke schneiden und die Tarte lauwarm oder bei Raumtemperatur servieren.","image_url":"/recetas/tarta-de-manzana-clasica/paso-08.webp","image_alt":"Klassische Apfeltarte mit Mürbeteig: Abkühlen und servieren"}],"image_url":"/recetas/tarta-de-manzana-clasica/portada.webp","gallery":[{"url":"/recetas/tarta-de-manzana-clasica/portada.webp","alt":"Klassische Apfeltarte mit Mürbeteig"}],"notes":"Verwenden Sie feste, leicht säuerliche Äpfel wie Granny Smith, Golden Delicious oder Boskoop, die beim Backen nicht zerfallen. Mit einem scharfen Messer schneiden, damit alle Scheiben gleich dick werden. Der Teig lässt sich am Vortag zubereiten und im Kühlschrank aufbewahren. Die Tarte hält sich abgedeckt 2 Tage bei Raumtemperatur oder 4 Tage im Kühlschrank; um sie wieder knusprig zu machen, 10 Minuten bei 160 °C aufwärmen.","nutrition":{"calories":346,"protein_g":4.4,"carbs_g":46,"fat_g":16.7,"sodium_mg":84,"serving_size":"1 Stück (1/8 der Tarte, etwa 140 g)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nährwerte je 100 g, multipliziert mit dem Gewicht der Zutaten und durch 8 Stücke geteilt: 250 g Mehl, 125 g ungesalzene Butter und 50 g Zucker für den Teig, 50 g Ei, 1,5 g Salz, 650 g geschälter und entkernter Apfel, 25 g Zitronensaft, 40 g Zucker, 2,6 g Zimt und 30 g ungesalzene Butter für den Belag, alles gezählt.","note":"Schätzung pro Stück. Die Werte hängen von der Größe der Äpfel und der Dicke des Teigs ab."},"seo":{"title":"Klassische Apfeltarte mit Mürbeteig selber machen | Manual de Cocina","description":"Klassische Apfeltarte mit selbstgemachtem Mürbeteig und dünn geschnittenen Äpfeln mit Zimt. 24-cm-Form, 8 Stücke. Schritt für Schritt mit Fotos.","image_variants":["/recetas/tarta-de-manzana-clasica/portada-1x1.webp","/recetas/tarta-de-manzana-clasica/portada-4x3.webp","/recetas/tarta-de-manzana-clasica/portada-16x9.webp"],"faq":[{"q":"Welche Äpfel eignen sich am besten für eine Apfeltarte?","a":"Feste, leicht säuerliche Äpfel wie Granny Smith, Golden Delicious oder Boskoop, denn sie behalten beim Backen ihre Form und gleichen die Süße aus."},{"q":"Warum muss der Teig vor dem Ausrollen kühlen?","a":"Die 30 Minuten im Kühlschrank kühlen die Butter und entspannen den Teig. So lässt er sich besser ausrollen, schrumpft beim Backen nicht und wird knusprig."},{"q":"Wie lange hält sich die Apfeltarte?","a":"Abgedeckt bis zu 2 Tage bei Raumtemperatur und 4 Tage im Kühlschrank. Um sie wieder knusprig zu machen, 10 Minuten bei 160 °C aufwärmen."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"cbf29e87-a523-5fbc-bdba-f866f12a0fe2","recipe_group_id":"5ac97df2-0a4e-4f3b-8bf3-ef91206b074d","language":"en","slug":"classic-apple-tart","public_path":"/en/classic-apple-tart","source_url":null,"title":"Classic Apple Tart with Shortcrust Pastry","excerpt":"Classic apple tart with homemade shortcrust pastry and thinly sliced cinnamon apples. Baked in a 24 cm pan, serves 8.","summary":"This apple tart has a shortcrust pastry made with flour, cold butter and egg, and a filling of thinly sliced apples with lemon, sugar and cinnamon. The slices are arranged in concentric circles, and the tart bakes until the edges are golden and crisp.\n\nIt takes 60 minutes of prep, 30 of them resting the dough, and 45 in the oven. It serves 8 in a 24 cm pan.","category":"Desserts","difficulty":"Medium","course":"Dessert","cuisine":"International","prep_time_minutes":60,"cook_time_minutes":45,"total_time_minutes":105,"servings":8,"keywords":["apple tart","apple tart recipe","classic apple tart","how to make apple tart","apple tart with shortcrust pastry","homemade apple tart","cinnamon apple tart"],"ingredients":[{"name":"all-purpose flour","amount":"250","unit":"g","group":"For the pastry"},{"name":"cold unsalted butter","amount":"125","unit":"g","group":"For the pastry"},{"name":"sugar","amount":"50","unit":"g","group":"For the pastry"},{"name":"egg","amount":"1","unit":"","group":"For the pastry"},{"name":"salt","amount":"1/4","unit":"teaspoon","group":"For the pastry"},{"name":"apples","amount":"5","unit":"","group":"For the filling"},{"name":"lemon","amount":"1/2","unit":"","group":"For the filling"},{"name":"sugar","amount":"40","unit":"g","group":"For the filling"},{"name":"ground cinnamon","amount":"1","unit":"teaspoon","group":"For the filling"},{"name":"unsalted butter","amount":"30","unit":"g","group":"For the filling"}],"steps":[{"title":"Prepare the ingredients","content":"Have ready 250 g flour, 125 g very cold unsalted butter, 50 g sugar, 1 egg, salt, 5 apples, 1 lemon and cinnamon. For the filling you also need 40 g sugar and 30 g butter. The colder the butter, the crisper the pastry.","image_url":"/recetas/tarta-de-manzana-clasica/paso-01.webp","image_alt":"Classic Apple Tart with Shortcrust Pastry: Prepare the ingredients"},{"title":"Make the pastry","content":"In a large bowl, mix 250 g flour, 50 g sugar and ¼ teaspoon salt. Add 125 g cold cubed butter and rub it in with your fingertips until it looks like coarse sand. Add the egg and bring the dough together without overworking it; if it is dry, add a few drops of cold water.","image_url":"/recetas/tarta-de-manzana-clasica/paso-02.webp","image_alt":"Classic Apple Tart with Shortcrust Pastry: Make the pastry"},{"title":"Rest the dough","content":"Shape the dough into a flat disk, wrap it in plastic wrap and rest it in the fridge for 30 minutes. Meanwhile, preheat the oven to 190 °C (375 °F).","image_url":"/recetas/tarta-de-manzana-clasica/paso-03.webp","image_alt":"Classic Apple Tart with Shortcrust Pastry: Rest the dough"},{"title":"Slice the apples","content":"Peel and core the apples and cut them into 3 mm slices. Toss the slices with the juice of ½ lemon so they do not darken.","image_url":"/recetas/tarta-de-manzana-clasica/paso-04.webp","image_alt":"Classic Apple Tart with Shortcrust Pastry: Slice the apples"},{"title":"Line the pan","content":"Roll out the dough with a rolling pin to about 3 mm thick and line a 24 cm pan. Press it against the sides, trim the excess from the edge and prick the base with a fork.","image_url":"/recetas/tarta-de-manzana-clasica/paso-05.webp","image_alt":"Classic Apple Tart with Shortcrust Pastry: Line the pan"},{"title":"Assemble the tart","content":"Arrange the apple slices slightly overlapping in concentric circles. Mix 40 g sugar with 1 teaspoon cinnamon, sprinkle it over the top and dot with 30 g butter in small pieces.","image_url":"/recetas/tarta-de-manzana-clasica/paso-06.webp","image_alt":"Classic Apple Tart with Shortcrust Pastry: Assemble the tart"},{"title":"Bake","content":"Bake on the middle rack for 45 minutes, until the edges are golden and the apples are tender when pierced. If the top browns too soon, cover it with aluminum foil. Remove it and leave it on a wire rack.","image_url":"/recetas/tarta-de-manzana-clasica/paso-07.webp","image_alt":"Classic Apple Tart with Shortcrust Pastry: Bake"},{"title":"Cool and serve","content":"Let it cool for 20 minutes before unmolding. Cut 8 slices and serve the tart warm or at room temperature.","image_url":"/recetas/tarta-de-manzana-clasica/paso-08.webp","image_alt":"Classic Apple Tart with Shortcrust Pastry: Cool and serve"}],"image_url":"/recetas/tarta-de-manzana-clasica/portada.webp","gallery":[{"url":"/recetas/tarta-de-manzana-clasica/portada.webp","alt":"Classic Apple Tart with Shortcrust Pastry"}],"notes":"Use firm, slightly tart apples, such as Granny Smith, Golden Delicious or Braeburn, which do not fall apart when baked. Slice with a very sharp knife so all the slices are the same thickness. The dough can be made the day before and kept in the fridge. The tart keeps for 2 days at room temperature or 4 days in the fridge, covered; to bring back the crispness, warm it for 10 minutes at 160 °C (320 °F).","nutrition":{"calories":346,"protein_g":4.4,"carbs_g":46,"fat_g":16.7,"sodium_mg":84,"serving_size":"1 slice (1/8 of the tart, about 140 g)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nutrients per 100 g multiplied by the weights of the ingredients and divided by 8 servings: 250 g flour, 125 g unsalted butter and 50 g sugar for the pastry, 50 g egg, 1.5 g salt, 650 g peeled and cored apple, 25 g lemon juice, 40 g sugar, 2.6 g cinnamon and 30 g unsalted butter for the filling, all counted.","note":"Estimate per serving. Values change with the size of the apples and the thickness of the pastry."},"seo":{"title":"Classic Apple Tart with Homemade Shortcrust Pastry | Manual de Cocina","description":"Classic apple tart with homemade shortcrust pastry and thinly sliced cinnamon apples. 24 cm pan, serves 8. Step by step with photos.","image_variants":["/recetas/tarta-de-manzana-clasica/portada-1x1.webp","/recetas/tarta-de-manzana-clasica/portada-4x3.webp","/recetas/tarta-de-manzana-clasica/portada-16x9.webp"],"faq":[{"q":"Which apples are best for an apple tart?","a":"Firm, slightly tart apples, such as Granny Smith, Golden Delicious or Braeburn, because they hold their shape when baked and balance the sweetness."},{"q":"Why does the dough need to chill before rolling?","a":"Resting it for 30 minutes in the fridge cools the butter and relaxes the dough. It rolls out more easily, does not shrink in the oven and bakes up crisp."},{"q":"How long does apple tart keep?","a":"Up to 2 days at room temperature and 4 days in the fridge, covered. To bring back the crispness, warm it for 10 minutes at 160 °C (320 °F)."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"fbe2cef6-9056-50b9-8afb-2bb0bcfb7a0a","recipe_group_id":"5ac97df2-0a4e-4f3b-8bf3-ef91206b074d","language":"fr","slug":"tarte-aux-pommes-classique","public_path":"/fr/tarte-aux-pommes-classique","source_url":null,"title":"Tarte aux pommes classique à la pâte brisée","excerpt":"Tarte aux pommes classique avec une pâte brisée maison et des pommes en fines lamelles à la cannelle. Cuite dans un moule de 24 cm, pour 8 parts.","summary":"Cette tarte aux pommes repose sur une pâte brisée à la farine, au beurre froid et à l'œuf, garnie de pommes en fines lamelles avec du citron, du sucre et de la cannelle. Les lamelles sont disposées en cercles concentriques, et la tarte cuit jusqu'à ce que les bords soient dorés et croustillants.\n\nElle demande 60 minutes de préparation, dont 30 de repos de la pâte, et 45 de cuisson. Pour 8 parts dans un moule de 24 cm.","category":"Desserts","difficulty":"Moyenne","course":"Dessert","cuisine":"Internationale","prep_time_minutes":60,"cook_time_minutes":45,"total_time_minutes":105,"servings":8,"keywords":["tarte aux pommes","recette de tarte aux pommes","tarte aux pommes classique","comment faire une tarte aux pommes","tarte aux pommes à la pâte brisée","tarte aux pommes maison","tarte aux pommes à la cannelle"],"ingredients":[{"name":"farine de blé","amount":"250","unit":"g","group":"Pour la pâte"},{"name":"beurre doux froid","amount":"125","unit":"g","group":"Pour la pâte"},{"name":"sucre","amount":"50","unit":"g","group":"Pour la pâte"},{"name":"œuf","amount":"1","unit":"","group":"Pour la pâte"},{"name":"sel","amount":"1/4","unit":"cuillère à café","group":"Pour la pâte"},{"name":"pommes","amount":"5","unit":"","group":"Pour la garniture"},{"name":"citron","amount":"1/2","unit":"","group":"Pour la garniture"},{"name":"sucre","amount":"40","unit":"g","group":"Pour la garniture"},{"name":"cannelle en poudre","amount":"1","unit":"cuillère à café","group":"Pour la garniture"},{"name":"beurre doux","amount":"30","unit":"g","group":"Pour la garniture"}],"steps":[{"title":"Préparer les ingrédients","content":"Prévoir 250 g de farine, 125 g de beurre doux très froid, 50 g de sucre, 1 œuf, du sel, 5 pommes, 1 citron et de la cannelle. Pour la garniture, il faut aussi 40 g de sucre et 30 g de beurre. Plus le beurre est froid, plus la pâte sera croustillante.","image_url":"/recetas/tarta-de-manzana-clasica/paso-01.webp","image_alt":"Tarte aux pommes classique à la pâte brisée: Préparer les ingrédients"},{"title":"Préparer la pâte","content":"Dans un grand saladier, mélanger 250 g de farine, 50 g de sucre et ¼ de cuillère à café de sel. Ajouter 125 g de beurre froid en dés et l'émietter du bout des doigts jusqu'à obtenir un sable grossier. Ajouter l'œuf et rassembler la pâte sans trop la travailler ; si elle est sèche, ajouter quelques gouttes d'eau froide.","image_url":"/recetas/tarta-de-manzana-clasica/paso-02.webp","image_alt":"Tarte aux pommes classique à la pâte brisée: Préparer la pâte"},{"title":"Laisser reposer la pâte","content":"Former un disque plat, l'envelopper dans du film alimentaire et le laisser reposer 30 minutes au réfrigérateur. Pendant ce temps, préchauffer le four à 190 °C.","image_url":"/recetas/tarta-de-manzana-clasica/paso-03.webp","image_alt":"Tarte aux pommes classique à la pâte brisée: Laisser reposer la pâte"},{"title":"Couper les pommes","content":"Éplucher les pommes, retirer le cœur et les couper en lamelles de 3 mm. Mélanger les lamelles avec le jus d'un demi-citron pour qu'elles ne noircissent pas.","image_url":"/recetas/tarta-de-manzana-clasica/paso-04.webp","image_alt":"Tarte aux pommes classique à la pâte brisée: Couper les pommes"},{"title":"Foncer le moule","content":"Étaler la pâte au rouleau sur environ 3 mm d'épaisseur et en garnir un moule de 24 cm. La presser contre les parois, couper l'excédent du bord et piquer le fond à la fourchette.","image_url":"/recetas/tarta-de-manzana-clasica/paso-05.webp","image_alt":"Tarte aux pommes classique à la pâte brisée: Foncer le moule"},{"title":"Monter la tarte","content":"Disposer les lamelles de pomme en les faisant légèrement se chevaucher, en cercles concentriques. Mélanger 40 g de sucre avec 1 cuillère à café de cannelle, saupoudrer et répartir 30 g de beurre en petits morceaux.","image_url":"/recetas/tarta-de-manzana-clasica/paso-06.webp","image_alt":"Tarte aux pommes classique à la pâte brisée: Monter la tarte"},{"title":"Cuire","content":"Cuire sur la grille du milieu pendant 45 minutes, jusqu'à ce que les bords soient dorés et que les pommes soient tendres à la piqûre. Si le dessus dore trop vite, le couvrir de papier d'aluminium. Sortir la tarte et la poser sur une grille.","image_url":"/recetas/tarta-de-manzana-clasica/paso-07.webp","image_alt":"Tarte aux pommes classique à la pâte brisée: Cuire"},{"title":"Laisser refroidir et servir","content":"Laisser refroidir 20 minutes avant de démouler. Couper 8 parts et servir la tarte tiède ou à température ambiante.","image_url":"/recetas/tarta-de-manzana-clasica/paso-08.webp","image_alt":"Tarte aux pommes classique à la pâte brisée: Laisser refroidir et servir"}],"image_url":"/recetas/tarta-de-manzana-clasica/portada.webp","gallery":[{"url":"/recetas/tarta-de-manzana-clasica/portada.webp","alt":"Tarte aux pommes classique à la pâte brisée"}],"notes":"Utilisez des pommes fermes et légèrement acidulées, comme la Granny Smith, la Golden ou la Reine des reinettes, qui ne se défont pas à la cuisson. Coupez avec un couteau bien aiguisé pour que toutes les lamelles aient la même épaisseur. La pâte peut être préparée la veille et gardée au réfrigérateur. La tarte se conserve 2 jours à température ambiante ou 4 jours au réfrigérateur, couverte ; pour retrouver le croustillant, la réchauffer 10 minutes à 160 °C.","nutrition":{"calories":346,"protein_g":4.4,"carbs_g":46,"fat_g":16.7,"sodium_mg":84,"serving_size":"1 part (1/8 de la tarte, environ 140 g)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somme des nutriments pour 100 g multipliés par le poids des ingrédients et divisés par 8 parts : 250 g de farine, 125 g de beurre doux et 50 g de sucre pour la pâte, 50 g d'œuf, 1,5 g de sel, 650 g de pomme épluchée et évidée, 25 g de jus de citron, 40 g de sucre, 2,6 g de cannelle et 30 g de beurre doux pour la garniture, le tout compté.","note":"Estimation par part. Les valeurs varient selon la taille des pommes et l'épaisseur de la pâte."},"seo":{"title":"Tarte aux pommes classique à la pâte brisée maison | Manual de Cocina","description":"Tarte aux pommes classique avec pâte brisée maison et pommes en fines lamelles à la cannelle. Moule de 24 cm, 8 parts. Pas à pas en photos.","image_variants":["/recetas/tarta-de-manzana-clasica/portada-1x1.webp","/recetas/tarta-de-manzana-clasica/portada-4x3.webp","/recetas/tarta-de-manzana-clasica/portada-16x9.webp"],"faq":[{"q":"Quelles pommes choisir pour une tarte aux pommes ?","a":"Des pommes fermes et légèrement acidulées, comme la Granny Smith, la Golden ou la Reine des reinettes, car elles gardent leur forme à la cuisson et équilibrent la douceur."},{"q":"Pourquoi faut-il refroidir la pâte avant de l'étaler ?","a":"Un repos de 30 minutes au réfrigérateur refroidit le beurre et détend la pâte. Elle s'étale mieux, ne rétrécit pas à la cuisson et reste croustillante."},{"q":"Combien de temps se conserve la tarte aux pommes ?","a":"Jusqu'à 2 jours à température ambiante et 4 jours au réfrigérateur, couverte. Pour retrouver le croustillant, la réchauffer 10 minutes à 160 °C."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"fc99cf40-5747-5c42-b167-d497abe700ff","recipe_group_id":"5ac97df2-0a4e-4f3b-8bf3-ef91206b074d","language":"it","slug":"crostata-di-mele-classica","public_path":"/it/crostata-di-mele-classica","source_url":null,"title":"Crostata di mele classica con pasta frolla","excerpt":"Crostata di mele classica con pasta frolla fatta in casa e mele a fettine sottili con cannella. Cotta in uno stampo da 24 cm, per 8 porzioni.","summary":"Questa crostata di mele ha una pasta frolla di farina, burro freddo e uovo e un ripieno di mele a fettine sottili con limone, zucchero e cannella. Le fettine si dispongono in cerchi concentrici e la crostata cuoce finché i bordi sono dorati e croccanti.\n\nRichiede 60 minuti di preparazione, di cui 30 di riposo della pasta, e 45 di forno. Per 8 porzioni in uno stampo da 24 cm.","category":"Dolci","difficulty":"Media","course":"Dolce","cuisine":"Internazionale","prep_time_minutes":60,"cook_time_minutes":45,"total_time_minutes":105,"servings":8,"keywords":["crostata di mele","ricetta crostata di mele","crostata di mele classica","come fare la crostata di mele","crostata di mele con pasta frolla","crostata di mele fatta in casa","crostata di mele con cannella"],"ingredients":[{"name":"farina 00","amount":"250","unit":"g","group":"Per la pasta"},{"name":"burro non salato freddo","amount":"125","unit":"g","group":"Per la pasta"},{"name":"zucchero","amount":"50","unit":"g","group":"Per la pasta"},{"name":"uovo","amount":"1","unit":"","group":"Per la pasta"},{"name":"sale","amount":"1/4","unit":"cucchiaino","group":"Per la pasta"},{"name":"mele","amount":"5","unit":"","group":"Per il ripieno"},{"name":"limone","amount":"1/2","unit":"","group":"Per il ripieno"},{"name":"zucchero","amount":"40","unit":"g","group":"Per il ripieno"},{"name":"cannella in polvere","amount":"1","unit":"cucchiaino","group":"Per il ripieno"},{"name":"burro non salato","amount":"30","unit":"g","group":"Per il ripieno"}],"steps":[{"title":"Prepara gli ingredienti","content":"Tieni pronti 250 g di farina, 125 g di burro non salato ben freddo, 50 g di zucchero, 1 uovo, sale, 5 mele, 1 limone e cannella. Per il ripieno servono anche 40 g di zucchero e 30 g di burro. Più il burro è freddo, più la pasta sarà croccante.","image_url":"/recetas/tarta-de-manzana-clasica/paso-01.webp","image_alt":"Crostata di mele classica con pasta frolla: Prepara gli ingredienti"},{"title":"Prepara la pasta","content":"In una ciotola grande mescola 250 g di farina, 50 g di zucchero e ¼ di cucchiaino di sale. Aggiungi 125 g di burro freddo a cubetti e sbriciolalo con la punta delle dita fino a ottenere una sabbia grossa. Unisci l'uovo e compatta l'impasto senza lavorarlo troppo; se è asciutto, aggiungi qualche goccia di acqua fredda.","image_url":"/recetas/tarta-de-manzana-clasica/paso-02.webp","image_alt":"Crostata di mele classica con pasta frolla: Prepara la pasta"},{"title":"Fai riposare la pasta","content":"Forma un disco piatto, avvolgilo nella pellicola trasparente e lascialo riposare 30 minuti in frigorifero. Nel frattempo preriscalda il forno a 190 °C.","image_url":"/recetas/tarta-de-manzana-clasica/paso-03.webp","image_alt":"Crostata di mele classica con pasta frolla: Fai riposare la pasta"},{"title":"Taglia le mele","content":"Sbuccia le mele, togli il torsolo e tagliale a fettine di 3 mm. Mescola le fettine con il succo di ½ limone perché non anneriscano.","image_url":"/recetas/tarta-de-manzana-clasica/paso-04.webp","image_alt":"Crostata di mele classica con pasta frolla: Taglia le mele"},{"title":"Fodera lo stampo","content":"Stendi la pasta con il mattarello a circa 3 mm di spessore e fodera uno stampo da 24 cm. Premila contro i bordi, elimina l'eccesso e bucherella la base con una forchetta.","image_url":"/recetas/tarta-de-manzana-clasica/paso-05.webp","image_alt":"Crostata di mele classica con pasta frolla: Fodera lo stampo"},{"title":"Monta la crostata","content":"Disponi le fettine di mela leggermente sovrapposte, in cerchi concentrici. Mescola 40 g di zucchero con 1 cucchiaino di cannella, spolvera sopra e distribuisci 30 g di burro a pezzetti.","image_url":"/recetas/tarta-de-manzana-clasica/paso-06.webp","image_alt":"Crostata di mele classica con pasta frolla: Monta la crostata"},{"title":"Inforna","content":"Cuoci sul ripiano centrale per 45 minuti, finché i bordi sono dorati e le mele sono tenere alla puntura. Se la superficie scurisce troppo presto, coprila con un foglio di alluminio. Sfornala e lasciala su una griglia.","image_url":"/recetas/tarta-de-manzana-clasica/paso-07.webp","image_alt":"Crostata di mele classica con pasta frolla: Inforna"},{"title":"Raffredda e servi","content":"Lascia raffreddare 20 minuti prima di sformare. Taglia 8 porzioni e servi la crostata tiepida o a temperatura ambiente.","image_url":"/recetas/tarta-de-manzana-clasica/paso-08.webp","image_alt":"Crostata di mele classica con pasta frolla: Raffredda e servi"}],"image_url":"/recetas/tarta-de-manzana-clasica/portada.webp","gallery":[{"url":"/recetas/tarta-de-manzana-clasica/portada.webp","alt":"Crostata di mele classica con pasta frolla"}],"notes":"Usa mele sode e leggermente acidule, come Granny Smith, Golden o Renetta, che non si sfaldano in cottura. Taglia con un coltello molto affilato perché tutte le fettine abbiano lo stesso spessore. La pasta si può preparare il giorno prima e conservare in frigorifero. La crostata si conserva 2 giorni a temperatura ambiente o 4 giorni in frigorifero, coperta; per ridarle croccantezza, scaldala 10 minuti a 160 °C.","nutrition":{"calories":346,"protein_g":4.4,"carbs_g":46,"fat_g":16.7,"sodium_mg":84,"serving_size":"1 porzione (1/8 di crostata, circa 140 g)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somma dei nutrienti per 100 g moltiplicati per i pesi degli ingredienti e divisi per 8 porzioni: 250 g di farina, 125 g di burro non salato e 50 g di zucchero per la pasta, 50 g di uovo, 1,5 g di sale, 650 g di mela sbucciata e senza torsolo, 25 g di succo di limone, 40 g di zucchero, 2,6 g di cannella e 30 g di burro non salato per il ripieno, tutto contato.","note":"Stima per porzione. I valori cambiano con la grandezza delle mele e lo spessore della pasta."},"seo":{"title":"Crostata di mele classica con pasta frolla fatta in casa | Manual de Cocina","description":"Crostata di mele classica con pasta frolla fatta in casa e mele a fettine sottili con cannella. Stampo da 24 cm, 8 porzioni. Passo dopo passo con foto.","image_variants":["/recetas/tarta-de-manzana-clasica/portada-1x1.webp","/recetas/tarta-de-manzana-clasica/portada-4x3.webp","/recetas/tarta-de-manzana-clasica/portada-16x9.webp"],"faq":[{"q":"Quali mele sono le migliori per la crostata di mele?","a":"Quelle sode e leggermente acidule, come Granny Smith, Golden o Renetta, perché mantengono la forma in cottura e bilanciano la dolcezza."},{"q":"Perché la pasta va fatta riposare prima di stenderla?","a":"Il riposo di 30 minuti in frigorifero raffredda il burro e rilassa l'impasto. Si stende meglio, non si restringe in forno e resta croccante."},{"q":"Quanto si conserva la crostata di mele?","a":"Fino a 2 giorni a temperatura ambiente e 4 giorni in frigorifero, coperta. Per ridarle croccantezza, scaldala 10 minuti a 160 °C."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"0f4879ee-f575-5c83-8968-f54d77505398","recipe_group_id":"5ac97df2-0a4e-4f3b-8bf3-ef91206b074d","language":"ja","slug":"りんごのタルト","public_path":"/ja/りんごのタルト","source_url":null,"title":"クラシックなりんごのタルト","excerpt":"手作りのサクサクのタルト生地に、薄切りのりんごとシナモンをのせたクラシックなりんごのタルト。24cmの型で焼いて、8人分です。","summary":"このりんごのタルトは、小麦粉、冷たいバター、卵で作るタルト生地に、レモン、砂糖、シナモンをからめた薄切りのりんごをのせます。りんごを同心円状に並べ、縁がこんがりきつね色になるまで焼きます。\n\n準備60分（うち生地を休ませる時間30分）、オーブン45分です。24cmの型で8人分です。","category":"デザート","difficulty":"普通","course":"デザート","cuisine":"インターナショナル","prep_time_minutes":60,"cook_time_minutes":45,"total_time_minutes":105,"servings":8,"keywords":["りんごのタルト","りんごのタルト レシピ","りんごのタルト 作り方","クラシック りんごのタルト","手作り りんごのタルト","りんごのタルト シナモン","タルト生地 りんご"],"ingredients":[{"name":"薄力粉","amount":"250","unit":"g","group":"生地用"},{"name":"無塩バター（冷たいもの）","amount":"125","unit":"g","group":"生地用"},{"name":"砂糖","amount":"50","unit":"g","group":"生地用"},{"name":"卵","amount":"1","unit":"","group":"生地用"},{"name":"塩","amount":"1/4","unit":"小さじ","group":"生地用"},{"name":"りんご","amount":"5","unit":"","group":"フィリング用"},{"name":"レモン","amount":"1/2","unit":"","group":"フィリング用"},{"name":"砂糖","amount":"40","unit":"g","group":"フィリング用"},{"name":"シナモンパウダー","amount":"1","unit":"小さじ","group":"フィリング用"},{"name":"無塩バター","amount":"30","unit":"g","group":"フィリング用"}],"steps":[{"title":"材料を準備する","content":"薄力粉250g、よく冷えた無塩バター125g、砂糖50g、卵1個、塩、りんご5個、レモン1個、シナモンを用意します。フィリング用に砂糖40gとバター30gも用意します。バターが冷たいほど、生地がサクサクに仕上がります。","image_url":"/recetas/tarta-de-manzana-clasica/paso-01.webp","image_alt":"クラシックなりんごのタルト: 材料を準備する"},{"title":"生地を作る","content":"大きめのボウルに薄力粉250g、砂糖50g、塩小さじ¼を入れて混ぜます。角切りにした冷たいバター125gを加え、指先ですり混ぜて粗い砂のような状態にします。卵を加え、こねすぎないようにまとめます。乾いているときは冷水を数滴加えます。","image_url":"/recetas/tarta-de-manzana-clasica/paso-02.webp","image_alt":"クラシックなりんごのタルト: 生地を作る"},{"title":"生地を休ませる","content":"生地を平らな円盤状にしてラップで包み、冷蔵庫で30分休ませます。その間にオーブンを190℃に予熱します。","image_url":"/recetas/tarta-de-manzana-clasica/paso-03.webp","image_alt":"クラシックなりんごのタルト: 生地を休ませる"},{"title":"りんごを切る","content":"りんごの皮をむいて芯を取り、3mmの薄切りにします。変色しないように、レモン½個の果汁をからめます。","image_url":"/recetas/tarta-de-manzana-clasica/paso-04.webp","image_alt":"クラシックなりんごのタルト: りんごを切る"},{"title":"型に敷く","content":"生地をめん棒で約3mmの厚さにのばし、24cmの型に敷きます。側面に沿わせて押さえ、はみ出した縁を切り落とし、底にフォークで穴を開けます。","image_url":"/recetas/tarta-de-manzana-clasica/paso-05.webp","image_alt":"クラシックなりんごのタルト: 型に敷く"},{"title":"タルトを組み立てる","content":"りんごの薄切りを少しずつ重ねながら、同心円状に並べます。砂糖40gとシナモン小さじ1を混ぜて全体にふり、バター30gを小さく切って散らします。","image_url":"/recetas/tarta-de-manzana-clasica/paso-06.webp","image_alt":"クラシックなりんごのタルト: タルトを組み立てる"},{"title":"焼く","content":"オーブンの中段で45分、縁がきつね色になり、りんごに串を刺してやわらかくなるまで焼きます。表面が早く焦げそうなときは、アルミホイルをかぶせます。取り出して網の上に置きます。","image_url":"/recetas/tarta-de-manzana-clasica/paso-07.webp","image_alt":"クラシックなりんごのタルト: 焼く"},{"title":"冷まして盛りつける","content":"型から外す前に20分冷まします。8等分に切り分け、温かいままか常温で盛りつけます。","image_url":"/recetas/tarta-de-manzana-clasica/paso-08.webp","image_alt":"クラシックなりんごのタルト: 冷まして盛りつける"}],"image_url":"/recetas/tarta-de-manzana-clasica/portada.webp","gallery":[{"url":"/recetas/tarta-de-manzana-clasica/portada.webp","alt":"クラシックなりんごのタルト"}],"notes":"焼いても崩れにくい、かためで少し酸味のあるりんご（グラニースミス、ゴールデン、紅玉など）を使ってください。薄切りは、切れ味のよい包丁を使うと、厚さがそろいます。生地は前日に作って冷蔵庫で保存できます。タルトは、ふたをして常温で2日、冷蔵庫で4日保存できます。サクサク感を戻すには、160℃で10分温めます。","nutrition":{"calories":346,"protein_g":4.4,"carbs_g":46,"fat_g":16.7,"sodium_mg":84,"serving_size":"1切れ（タルトの1/8、約140g）","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"100gあたりの栄養素に材料の重量を掛け、8人分で割って合計しています。生地用の薄力粉250g、無塩バター125g、砂糖50g、卵50g、塩1.5g、皮をむいて芯を取ったりんご650g、レモン果汁25g、フィリング用の砂糖40g、シナモン2.6g、無塩バター30gを使用しています。すべて全量を計算しています。","note":"1切れの目安です。りんごの大きさや生地の厚さによって値が変わります。"},"seo":{"title":"クラシックなりんごのタルトの作り方｜手作りタルト生地 | Manual de Cocina","description":"手作りのタルト生地に、薄切りのりんごとシナモンをのせたクラシックなりんごのタルト。24cmの型で8人分。作り方を写真付きで解説します。","image_variants":["/recetas/tarta-de-manzana-clasica/portada-1x1.webp","/recetas/tarta-de-manzana-clasica/portada-4x3.webp","/recetas/tarta-de-manzana-clasica/portada-16x9.webp"],"faq":[{"q":"りんごのタルトにはどんなりんごが向いていますか？","a":"グラニースミス、ゴールデン、紅玉など、かためで少し酸味のあるりんごです。焼いても形が崩れにくく、甘さのバランスもよくなります。"},{"q":"生地はなぜのばす前に冷やすのですか？","a":"冷蔵庫で30分休ませると、バターが冷えて生地がゆるみます。のばしやすく、焼いても縮みにくく、サクサクに仕上がります。"},{"q":"りんごのタルトはどれくらい日持ちしますか？","a":"ふたをして、常温で2日、冷蔵庫で4日です。サクサク感を戻すには、160℃で10分温めます。"}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"8198975c-9a76-56fc-8465-5333593a8f85","recipe_group_id":"5ac97df2-0a4e-4f3b-8bf3-ef91206b074d","language":"pt","slug":"torta-de-maca-classica","public_path":"/pt/torta-de-maca-classica","source_url":null,"title":"Torta de maçã clássica com massa podre","excerpt":"Torta de maçã clássica com massa podre caseira e maçãs em fatias finas com canela. Assada em uma forma de 24 cm, rende 8 porções.","summary":"Esta torta de maçã tem uma massa podre de farinha, manteiga gelada e ovo e um recheio de maçãs em fatias finas com limão, açúcar e canela. As fatias são dispostas em círculos concêntricos, e a torta assa até as bordas ficarem douradas e crocantes.\n\nLeva 60 minutos de preparo, 30 deles de descanso da massa, e 45 de forno. Rende 8 porções em uma forma de 24 cm.","category":"Sobremesas","difficulty":"Média","course":"Sobremesa","cuisine":"Internacional","prep_time_minutes":60,"cook_time_minutes":45,"total_time_minutes":105,"servings":8,"keywords":["torta de maçã","receita de torta de maçã","torta de maçã clássica","como fazer torta de maçã","torta de maçã com massa podre","torta de maçã caseira","torta de maçã com canela"],"ingredients":[{"name":"farinha de trigo","amount":"250","unit":"g","group":"Para a massa"},{"name":"manteiga sem sal gelada","amount":"125","unit":"g","group":"Para a massa"},{"name":"açúcar","amount":"50","unit":"g","group":"Para a massa"},{"name":"ovo","amount":"1","unit":"","group":"Para a massa"},{"name":"sal","amount":"1/4","unit":"colher de chá","group":"Para a massa"},{"name":"maçãs","amount":"5","unit":"","group":"Para o recheio"},{"name":"limão","amount":"1/2","unit":"","group":"Para o recheio"},{"name":"açúcar","amount":"40","unit":"g","group":"Para o recheio"},{"name":"canela em pó","amount":"1","unit":"colher de chá","group":"Para o recheio"},{"name":"manteiga sem sal","amount":"30","unit":"g","group":"Para o recheio"}],"steps":[{"title":"Separe os ingredientes","content":"Tenha à mão 250 g de farinha, 125 g de manteiga sem sal bem gelada, 50 g de açúcar, 1 ovo, sal, 5 maçãs, 1 limão e canela. Para o recheio, você precisa também de 40 g de açúcar e 30 g de manteiga. Quanto mais gelada a manteiga, mais crocante fica a massa.","image_url":"/recetas/tarta-de-manzana-clasica/paso-01.webp","image_alt":"Torta de maçã clássica com massa podre: Separe os ingredientes"},{"title":"Faça a massa","content":"Em uma tigela grande, misture 250 g de farinha, 50 g de açúcar e ¼ de colher de chá de sal. Junte 125 g de manteiga gelada em cubos e esfarele com a ponta dos dedos até parecer areia grossa. Acrescente o ovo e una a massa sem sová-la demais; se ficar seca, adicione algumas gotas de água gelada.","image_url":"/recetas/tarta-de-manzana-clasica/paso-02.webp","image_alt":"Torta de maçã clássica com massa podre: Faça a massa"},{"title":"Deixe a massa descansar","content":"Forme um disco achatado, embrulhe em filme plástico e deixe descansar 30 minutos na geladeira. Enquanto isso, preaqueça o forno a 190 °C.","image_url":"/recetas/tarta-de-manzana-clasica/paso-03.webp","image_alt":"Torta de maçã clássica com massa podre: Deixe a massa descansar"},{"title":"Corte as maçãs","content":"Descasque as maçãs, retire o miolo e corte em fatias de 3 mm. Misture as fatias com o suco de ½ limão para não escurecerem.","image_url":"/recetas/tarta-de-manzana-clasica/paso-04.webp","image_alt":"Torta de maçã clássica com massa podre: Corte as maçãs"},{"title":"Forre a forma","content":"Abra a massa com um rolo até cerca de 3 mm de espessura e forre uma forma de 24 cm. Pressione contra as laterais, apare o excesso da borda e fure o fundo com um garfo.","image_url":"/recetas/tarta-de-manzana-clasica/paso-05.webp","image_alt":"Torta de maçã clássica com massa podre: Forre a forma"},{"title":"Monte a torta","content":"Disponha as fatias de maçã ligeiramente sobrepostas, em círculos concêntricos. Misture 40 g de açúcar com 1 colher de chá de canela, polvilhe por cima e distribua 30 g de manteiga em pedacinhos.","image_url":"/recetas/tarta-de-manzana-clasica/paso-06.webp","image_alt":"Torta de maçã clássica com massa podre: Monte a torta"},{"title":"Asse","content":"Asse na grade do meio por 45 minutos, até as bordas ficarem douradas e as maçãs macias ao espetar. Se a superfície dourar cedo demais, cubra com papel-alumínio. Retire e deixe sobre uma grade.","image_url":"/recetas/tarta-de-manzana-clasica/paso-07.webp","image_alt":"Torta de maçã clássica com massa podre: Asse"},{"title":"Esfrie e sirva","content":"Deixe esfriar 20 minutos antes de desenformar. Corte 8 porções e sirva a torta morna ou em temperatura ambiente.","image_url":"/recetas/tarta-de-manzana-clasica/paso-08.webp","image_alt":"Torta de maçã clássica com massa podre: Esfrie e sirva"}],"image_url":"/recetas/tarta-de-manzana-clasica/portada.webp","gallery":[{"url":"/recetas/tarta-de-manzana-clasica/portada.webp","alt":"Torta de maçã clássica com massa podre"}],"notes":"Use maçãs firmes e levemente ácidas, como Granny Smith, Golden ou Fuji, que não desmancham no forno. Corte com uma faca bem afiada para que todas as fatias tenham a mesma espessura. A massa pode ser feita no dia anterior e guardada na geladeira. A torta dura 2 dias em temperatura ambiente ou 4 dias na geladeira, tampada; para devolver a crocância, aqueça por 10 minutos a 160 °C.","nutrition":{"calories":346,"protein_g":4.4,"carbs_g":46,"fat_g":16.7,"sodium_mg":84,"serving_size":"1 porção (1/8 da torta, cerca de 140 g)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Soma dos nutrientes por 100 g multiplicados pelo peso dos ingredientes e divididos por 8 porções: 250 g de farinha, 125 g de manteiga sem sal e 50 g de açúcar da massa, 50 g de ovo, 1,5 g de sal, 650 g de maçã descascada e sem miolo, 25 g de suco de limão, 40 g de açúcar, 2,6 g de canela e 30 g de manteiga sem sal do recheio, tudo contado.","note":"Estimativa por porção. Os valores mudam conforme o tamanho das maçãs e a espessura da massa."},"seo":{"title":"Torta de maçã clássica com massa podre caseira | Manual de Cocina","description":"Torta de maçã clássica com massa podre caseira e maçãs em fatias finas com canela. Forma de 24 cm, 8 porções. Passo a passo com fotos.","image_variants":["/recetas/tarta-de-manzana-clasica/portada-1x1.webp","/recetas/tarta-de-manzana-clasica/portada-4x3.webp","/recetas/tarta-de-manzana-clasica/portada-16x9.webp"],"faq":[{"q":"Quais maçãs são melhores para torta de maçã?","a":"As firmes e levemente ácidas, como Granny Smith, Golden ou Fuji, porque mantêm a forma no forno e equilibram a doçura."},{"q":"Por que a massa precisa gelar antes de ser aberta?","a":"Descansar 30 minutos na geladeira esfria a manteiga e relaxa a massa. Assim ela abre melhor, não encolhe no forno e fica crocante."},{"q":"Quanto tempo dura a torta de maçã?","a":"Até 2 dias em temperatura ambiente e 4 dias na geladeira, tampada. Para devolver a crocância, aqueça por 10 minutos a 160 °C."}]},"published":true,"editorial_status":"published","content_html":""}
]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/tarta-de-manzana-clasica') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    '', x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;
